<?php
use EIPSI\ExternalApi as A;
d2_case('Moderate load 100 participants times two items uses bounded batch queries and memory',function(){global$wpdb;$d=pe_definition('many');$p=d2_publish(false,$d);$option=null;foreach($d['nodes']as$n)if(($n['response_key']??null)==='R_q3')$option=$n['options'][0]['id'];for($i=0;$i<100;$i++){$f=pe_runtime()->handle($p['public']);$done=pe_runtime()->handle($p['public'],$f['token'],pe_request($f,'submit',array('R_q1'=>'MODERATE_'.$i,'R_q3'=>$option)));d2_assert($done['view']['next_action']['kind']==='FINISHED');}$k=d2_key(array($d['study']['logical_id']));$q=$wpdb->num_queries;$mem=memory_get_usage();memory_reset_peak_usage();$start=microtime(true);$r=d2_read($k,array(),$p);$jsonMs=round((microtime(true)-$start)*1000,3);$queries=$wpdb->num_queries-$q;$peak=memory_get_peak_usage()-$mem;d2_assert(count($r['items'])===200&&$queries<100&&$peak<33554432,'Batch budget exceeded');$start=microtime(true);$q=$wpdb->num_queries;$csv=d2_read($k,array('format'=>'csv'),$p);$csvMs=round((microtime(true)-$start)*1000,3);$csvQueries=$wpdb->num_queries-$q;$start=microtime(true);$q=$wpdb->num_queries;$dict=d2_read($k,array(),$p,true);$dictionaryMs=round((microtime(true)-$start)*1000,3);$dictionaryQueries=$wpdb->num_queries-$q;d2_assert(count($dict['items'])===2);echo 'METRIC '.json_encode(array('participants'=>100,'rows'=>200,'queries_json'=>$queries,'incremental_peak_bytes'=>$peak,'json_ms'=>$jsonMs,'csv_ms'=>$csvMs,'dictionary_ms'=>$dictionaryMs,'queries_csv'=>$csvQueries,'queries_dictionary'=>$dictionaryQueries,'csv_bytes'=>strlen($csv['csv'])))."\n";});
d2_case('Oversized definitions and execution hydration fail explicitly before loading blobs',function()use($wpdb){$p=d2_publish();$f=d2_finish($p);$k=d2_key(array($p['definition']['study']['logical_id']));$table=$wpdb->prefix.'eipsi_engine_study_executions';$id=$f['frame']['access']['execution_id'];$old=$wpdb->get_var($wpdb->prepare("SELECT checkpoint_json FROM $table WHERE id=%s",$id));try{$large=json_decode($old,true);$large['private_fixture_padding']=str_repeat('x',2097153);$wpdb->update($table,array('checkpoint_json'=>EIPSI\StudyEngine\Contracts\Canonical::json($large)),array('id'=>$id));d2_error(function()use($k,$p){d2_read($k,array(),$p);},422,'eipsi_external_export_limit_exceeded');}finally{$wpdb->update($table,array('checkpoint_json'=>$old),array('id'=>$id));}$vtable=$wpdb->prefix.'eipsi_engine_study_versions';$old=$wpdb->get_var($wpdb->prepare("SELECT metadata_json FROM $vtable WHERE id=%s",$p['version']));try{$wpdb->update($vtable,array('metadata_json'=>json_encode(array('fixture_padding'=>str_repeat('x',4194305)))),array('id'=>$p['version']));d2_error(function()use($k,$p){d2_read($k,array('format'=>'csv'),$p);},422,'eipsi_external_export_limit_exceeded');}finally{$wpdb->update($vtable,array('metadata_json'=>$old),array('id'=>$p['version']));}});
d2_case('Bulk capacity is explicit while a small JSON page does not accumulate the whole dataset',function(){ $d=pe_definition();foreach($d['nodes']as&$n)if($n['kind']==='QUESTION')$n['validation']['max_length']=100000;unset($n);$p=d2_publish(false,$d);for($i=0;$i<115;$i++)d2_finish($p,str_repeat('z',80000));$k=d2_key(array($p['definition']['study']['logical_id']));$page=d2_read($k,array('limit'=>1),$p);d2_assert(count($page['items'])===1&&$page['next_cursor']!==null);d2_error(function()use($k,$p){d2_read($k,array('format'=>'csv'),$p);},422,'eipsi_external_export_limit_exceeded');$http=d2_http($k,$p,array('format'=>'csv'));d2_assert($http['status']===422&&$http['data']['code']==='eipsi_external_export_limit_exceeded');$GLOBALS['api2_capacity_error']=$http['data'];echo 'CAPACITY '.json_encode(array('participants'=>115,'value_bytes_each'=>80000,'logical_value_bytes'=>9200000,'json_limit_1'=>'PASS','csv'=>'422 export_limit_exceeded','configured_bulk_bytes'=>8388608))."\n";});
